{% extends "smart_power/templates/print/base_rtl.html" %}
{%- set c = frappe.get_doc("SP Consignment Container", doc.container) -%}
{% block title %}
<table class="sp-quote-head">
	<tr>
		<td><h2>{{ _("Delivery Note") }}</h2><div>{{ _("No.") }}: <span class="sp-num">{{ doc.name }}</span></div></td>
		<td class="sp-quote-meta"><div>{{ _("Date") }}: {{ ar_date(doc.movement_date) }}</div></td>
	</tr>
</table>
{% endblock %}
{% block body %}
<p>{{ _("Handed over on behalf of {0}, from goods kept with Smart Power on consignment.").format(c.supplier) }}</p>
<table class="sp-table">
	<tbody>
		<tr><th>{{ _("Customer") }}</th><td>{{ doc.customer_name or "" }}{% if doc.customer_phone %} · <span class="sp-num">{{ doc.customer_phone }}</span>{% endif %}</td></tr>
		<tr><th>{{ _("Item") }}</th><td>{{ c.item_name or c.item }}</td></tr>
		<tr><th>{{ _("Quantity") }}</th><td class="sp-num"><strong>{{ doc.qty }}</strong></td></tr>
		<tr><th>{{ _("Container") }}</th><td class="sp-num">{{ c.container_no or c.name }}</td></tr>
		{%- if doc.note %}<tr><th>{{ _("Note") }}</th><td>{{ doc.note }}</td></tr>{% endif %}
	</tbody>
</table>
{% endblock %}
{% block signatures %}
{{ signature_block(_("Received by"), _("For Smart Power")) }}
{% endblock %}
